WITH факт(subject, n) AS (SELECT 'ST', count(*) FROM project_needs WHERE project_id = $1 UNION ALL SELECT 'FR', count(*) FROM project_requirements WHERE project_id = $1 AND kind = 'FR' UNION ALL SELECT 'NFR', count(*) FROM project_requirements WHERE project_id = $1 AND kind = 'NFR' UNION ALL SELECT 'US', count(*) FROM project_stories WHERE project_id = $1 UNION ALL SELECT 'TC', count(*) FROM project_checks WHERE project_id = $1) SELECT s.subject || ' — в сводке «Всего» ' || s.said || ', в наборе ' || f.n AS detail FROM project_traceability_said s JOIN факт f ON f.subject = s.subject WHERE s.project_id = $1 AND s.column_name = 'Всего' AND s.said <> f.n UNION ALL SELECT f.subject || ' — в наборе ' || f.n || ', а сводка о нём молчит' FROM факт f WHERE NOT EXISTS (SELECT 1 FROM project_traceability_said s WHERE s.project_id = $1 AND s.column_name = 'Всего' AND s.subject = f.subject) ORDER BY 1
